const STY = (bg) => `position:absolute;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#ffffff;font-family:inherit;font-weight:800;line-height:1.1;opacity:0;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;
const B_OFF = `#1a1e2b`;

root.innerHTML = `
  <div id="c0" style="${STY(B_OFF)}top:60px;left:70px;width:800px;height:180px;font-size:52px;">U.S. PRO</div>
  <div id="c1" style="${STY(B_OFF)}top:270px;left:70px;width:800px;height:140px;font-size:46px;">AGE CHECK</div>
  <div id="c2" style="${STY(B1)}top:440px;left:70px;width:385px;height:350px;font-size:42px;">MAJOR<br>CARDS</div>
  <div id="c3" style="${STY(B2)}top:440px;left:485px;width:385px;height:350px;font-size:42px;">ORDER<br>RECORDS</div>
  <div id="foot" style="position:absolute;top:840px;width:100%;text-align:center;color:#ffffff;font-size:50px;font-weight:900;opacity:0;letter-spacing:-1px">CHATGPT WALLET</div>
`;

const els = [root.querySelector('#c0'), root.querySelector('#c1'), root.querySelector('#c2'), root.querySelector('#c3'), root.querySelector('#foot')];

function frame(t, p, d) {
  // Stage 1: Card 0 appears and activates
  const s0 = spr(t, 0.2, 0.8, 6);
  const active0 = p > 0.15;
  els[0].style.opacity = s0;
  els[0].style.transform = `translateY(${lerp(30, 0, s0)}px)`;
  els[0].style.background = active0 ? B1 : B_OFF;
  els[0].textContent = active0 ? 'U.S. PRO ACTIVE' : 'CHECKING STATUS...';

  // Stage 2: Card 1 appears and activates
  const s1 = spr(t, 0.6, 0.8, 6);
  const active1 = p > 0.3;
  els[1].style.opacity = s1;
  els[1].style.transform = `translateY(${lerp(30, 0, s1)}px)`;
  els[1].style.background = active1 ? B2 : B_OFF;
  els[1].textContent = active1 ? '18+ VERIFIED' : 'VERIFYING AGE...';

  // Stage 3: Support Cards slide in from sides
  const s2 = spr(t, 1.2, 0.8, 5);
  els[2].style.opacity = s2;
  els[2].style.transform = `translateX(${lerp(-60, 0, s2)}px)`;

  const s3 = spr(t, 1.4, 0.8, 5);
  els[3].style.opacity = s3;
  els[3].style.transform = `translateX(${lerp(60, 0, s3)}px)`;

  // Stage 4: Footer
  const sf = spr(t, 1.8, 0.8, 5);
  els[4].style.opacity = sf;
  els[4].style.transform = `scale(${lerp(0.9, 1, sf)})`;

  // Settle everything at p=0.55
  if (p >= 0.55) {
    els[0].style.opacity = 1;
    els[0].style.transform = 'none';
    els[0].style.background = B1;
    els[0].textContent = 'U.S. PRO ACTIVE';

    els[1].style.opacity = 1;
    els[1].style.transform = 'none';
    els[1].style.background = B2;
    els[1].textContent = '18+ VERIFIED';

    els[2].style.opacity = 1;
    els[2].style.transform = 'none';
    els[3].style.opacity = 1;
    els[3].style.transform = 'none';
    els[4].style.opacity = 1;
    els[4].style.transform = 'none';
  }
}
